package main

import (
	"encoding/json"
	"log"
	"net/http"
)

type Message struct {
	Message string `json:"message"`
}

func handler(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Path {
	case "/health":
		if r.Method != http.MethodGet {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok"})

	case "/echo":
		if r.Method != http.MethodPost {
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // 1 MiB limit
		var msg Message
		if err := json.NewDecoder(r.Body).Decode(&msg); err != nil {
			http.Error(w, "invalid JSON body", http.StatusBadRequest)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(msg)

	default:
		http.NotFound(w, r)
	}
}

func main() {
	log.Println("Listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", http.HandlerFunc(handler)))
}
```

Run with `go run main.go`. Try `curl http://localhost:8080/health` and `curl -X POST -H 'Content-Type: application/json' -d '{"message":"hello"}' http://localhost:8080/echo`.

### Evaluation

Assistant A’s answer is a substantially better response. Its sample server is mostly runnable and demonstrates both GET and POST endpoints, JSON handling, and basic error responses. One weakness is that `indexHandler` does not check the HTTP method, and registering `"/"` in Go’s default mux makes it a catch-all for otherwise unmatched paths; unknown URLs can therefore return the welcome message instead of a 404. The deprecated `ioutil.ReadAll` still works, but `io.ReadAll` is preferred in modern Go.

Assistant B offers a broader API design, but its code has multiple compile-time and runtime problems. For example, `r.URL.Query().Int()` does not exist, `count` is declared but unused, `okResp(w, u, http.StatusCreated)` passes too many arguments, and `http.NoContent(w)` is not a valid standard-library call. It also has a malformed server address (`":*" + *port`), missing imports, and an incorrect signal-handling snippet (`unix.Signal.Notify`). Its user-list slice can panic when the requested page exceeds the available users, and the initial `nextID` conflicts with the seeded users’ IDs. These issues make the code unsuitable as a working server despite the useful endpoint ideas.

